mapper.select:
SELECT * FROM plt_migration_source_record
WHERE tenant_id = #{query.tenantId}
  AND batch_id = #{query.batchId}
  AND id = #{query.sourceRecordId}
  AND deleted = b'0'
FOR UPDATE

SELECT s.*, CASE WHEN EXISTS (SELECT 1 FROM plt_external_key_mapping m WHERE m.tenant_id = s.tenant_id AND m.source_record_id = s.id AND m.result_type = 'MAPPED' AND m.deleted = b'0') THEN 'MAPPED' WHEN EXISTS (SELECT 1 FROM plt_migration_issue i WHERE i.tenant_id = s.tenant_id AND i.source_record_id = s.id AND i.deleted = b'0') THEN 'ISSUE' WHEN EXISTS (SELECT 1 FROM plt_external_key_mapping m WHERE m.tenant_id = s.tenant_id AND m.source_record_id = s.id AND m.result_type = 'RETAINED' AND m.deleted = b'0') THEN 'RETAINED' ELSE NULL END AS result_type FROM plt_migration_source_record s WHERE s.tenant_id = #{query.tenantId} AND s.batch_id = #{query.batchId} AND s.deleted = b'0'
AND s.id > #{query.afterSourceRecordId}
ORDER BY s.id ASC LIMIT #{query.limit}
